"""Immutable numbered signed versions; atomic publication at the unchanged CDP."""
import pathlib,datetime,json,sys,os,hashlib
from cryptography import x509
from cryptography.hazmat.primitives import hashes,serialization
R=pathlib.Path('/tmp/cvk-crlrefresh-20261104');number=int(sys.argv[1]);assert number in [1,2];now=datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0);root=x509.load_pem_x509_certificate((R/'root.crt').read_bytes());key=serialization.load_pem_private_key((R/'root.key').read_bytes(),None);old=x509.load_pem_x509_certificate((R/'original.crt').read_bytes());assert not (R/('crl-v'+str(number)+'.crl')).exists()
b=x509.CertificateRevocationListBuilder().issuer_name(root.subject).last_update(now-datetime.timedelta(seconds=5)).next_update(now+datetime.timedelta(minutes=10 if number==1 else 120)).add_extension(x509.CRLNumber(number),False).add_extension(x509.AuthorityKeyIdentifier.from_issuer_public_key(key.public_key()),False)
if number==2:b=b.add_revoked_certificate(x509.RevokedCertificateBuilder().serial_number(old.serial_number).revocation_date(now-datetime.timedelta(seconds=1)).add_extension(x509.CRLReason(x509.ReasonFlags.superseded),False).build())
c=b.sign(key,hashes.SHA256());der=c.public_bytes(serialization.Encoding.DER);pem=c.public_bytes(serialization.Encoding.PEM);name='crl-v'+str(number);(R/(name+'.crl')).write_bytes(der);(R/(name+'.pem')).write_bytes(pem);tmp=R/'issuer-next.crl';tmp.write_bytes(der);os.replace(tmp,R/'issuer.crl');mode=json.loads((R/'server-mode.json').read_text());mode['CRLversion']=number;tmp=R/'mode-next.json';tmp.write_text(json.dumps(mode));os.replace(tmp,R/'server-mode.json');(R/'root-current-crl.pem').write_bytes((R/'root.crt').read_bytes()+pem)
out={'publishedAtUTC':datetime.datetime.now(datetime.timezone.utc).isoformat(),'version':number,'sha256':hashlib.sha256(der).hexdigest(),'bytes':len(der),'lastUpdateUTC':c.last_update.replace(tzinfo=datetime.timezone.utc).isoformat(),'nextUpdateUTC':c.next_update.replace(tzinfo=datetime.timezone.utc).isoformat(),'revokedSerialsHex':[format(v.serial_number,'x') for v in c],'certificateOrPolicyChanged':False,'manualRefreshOrFlushIssued':False};(R/(name+'.json')).write_text(json.dumps(out,indent=2)+'\n');print('PUBLISHED CRL',json.dumps(out),flush=True)
